import{_ as e,c as a,o as i,b0 as l}from"./chunks/framework.Dmsv_Tiv.js";const r="/media-docs/assets/image-20241012070650615.CHdCgQ88.png",n="/media-docs/assets/image-20241012192911174.CCHzHukj.png",d="/media-docs/assets/image-20241012200228532.DsWUNLSt.png",P=JSON.parse('{"title":"LV035-JPEG中的Exif简介","description":null,"frontmatter":{"title":"LV035-JPEG中的Exif简介","date":"2025-10-09T14:54:05.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/image/img-file-format/126b0e34da3d05ba46e0bcc2","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-10-09T14:54:05.091Z","fulluuid":"a46e0bcc25dd46919e3b04f6cef12dff","useduuid":"a46e0bcc2"}},"headers":[],"relativePath":"sdoc/image/img-file-format/126b0e34da3d05ba46e0bcc2.md","filePath":"sdoc/01-图像/30-图像文件格式/LV035-JPEG中的Exif简介.md","lastUpdated":1767537778000}'),s={name:"sdoc/image/img-file-format/126b0e34da3d05ba46e0bcc2.md"};function o(c,t,f,x,g,E){return i(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="lv035-jpeg中的exif简介" tabindex="-1">LV035-JPEG中的Exif简介 <a class="header-anchor" href="#lv035-jpeg中的exif简介" aria-label="Permalink to &quot;LV035-JPEG中的Exif简介&quot;">​</a></h1><p>其实使用工具来分析JPEG图片就可以了，但是之前做项目的时候遇到了一种Exif结构的JPEG图片，内部包含的信息比JFIF的要多，要复杂，还包含了一张缩略图，缩略图的分辨率信息也是从FF C0开始的，由于获取图片分辨率的时候是直接查找FF C0，所以就获取到了错误分辨率，这里写个笔记，简单解析一下Exif格式图片中的一些额外的信息。</p><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>上一节的时候已经简单说明过：JPEG标准主要是围绕编解码的部分（如DCT变换、量化、哈夫曼树等等），虽然在JPEG标准中也定义了“<strong>JPEG Interchange Format (JIF)</strong>”的文件存储格式，但是因为Encoder和Decoder完整实现JIF很困难，且JIF标准也存在一些缺陷，因此JIF并没有被推广开来。后来出现的“<strong>JPEG File Interchange Format</strong> (JFIF)” 和 “**Exchange image file Format(**Exif)” 等新的存储格式成为了主流。Exif 和 JFIF 都是遵循 JIF标准的，两者只是在JIF的基础上增加了一些各自的Marker。</p><ul><li>JPEG是压缩标准，JPEG/JFIF和JPEG/Exif是文件格式标准，不是一个概念，需要注意区分。</li><li>JPEG/Exif文件格式标准是Camera产业联合会发布，主要用于摄像设备上，摄像产业把Exif作为行业的元数据（metadata)交换格式</li><li>JPEG/JFIF文件格式标准是为了方便JPEG压缩图像在广泛的平台和应用间以最小的存储空间代价进行交换而设计的，它不包含JPEG/TIFF标准任何高级特性。</li></ul><h2 id="二、图片元数据-metadata" tabindex="-1">二、图片元数据（Metadata） <a class="header-anchor" href="#二、图片元数据-metadata" aria-label="Permalink to &quot;二、图片元数据（Metadata）&quot;">​</a></h2><p>元数据（Metadata），又称中介数据、中继数据，为描述数据的数据（data about data），主要是描述数据属性（property）的信息。用来支持如指示存储位置、历史数据、资源查找、文件记录等功能。</p><p>图片元数据（Metadata） 是嵌入到图片文件中的一些标签。比较像文件属性，但是种类繁多。对于数码图像，目前常见的研数据有EXIF, IPTC和XMP三种：</p><ul><li>EXIF：通常被数码相机在拍摄照片时自动添加，比如相机型号、镜头、曝光、图片尺寸等信息</li><li>IPTF：比如图片标题、关键字、说明、作者、版权等信息。主要是由人工在后期通过软件写入的数据。</li><li>XMP：XMP实际上是一种元数据存储和管理的标准，可以将Exif，IPTC或其他的数据都按XMP统一的格式存放在图像文件中。 但是当將JPG转换为其它格式如png， pdf等时，由于这些格式都不支持Exif格式，所以Exif信息就会丢失。为了解决这个问题，Adobe公司推出用XMP管理元数据的方法，即将图像中的元数据如Exif，IPTC等都纳入XMP库中，由XMP管理。</li></ul><p>元数据的嵌入方式因图像格式而异，不同格式的图像文件有不同的嵌入方式。如JPG、TIF就是EXIF。</p><h2 id="三、exif是什么" tabindex="-1">三、Exif是什么？ <a class="header-anchor" href="#三、exif是什么" aria-label="Permalink to &quot;三、Exif是什么？&quot;">​</a></h2><p>Exif为<strong>Exchangeable Image File</strong>(可交换图像文件)的缩写，是专门为数码相机的照片设定的，就是用来记录拍摄图像时的各种信息：图像信息（厂商，分辨率等），相机拍摄记录（ISO，白平衡，饱和度，锐度等），缩略图（缩略图宽度，高度等），gps（拍摄时的经度，纬度，高度）等，将这些信息按照JPEG文件标准放在图像文件头部。</p><blockquote><p>Exif所记录主要的几类信息：</p><ul><li>拍摄信息</li><li>拍摄器材（机身、镜头、闪光灯等）</li><li>拍摄参数（快门速度、光圈F值、ISO速度、焦距、测光模式等）</li><li>图像处理数（锐化、对比度、饱和度、白平衡等）</li><li>图像描述及版权信息</li><li>GPS定位数据</li><li>缩略图</li></ul><p>Exif最初由日本电子工业发展协会(JEIDA --J<strong>apan Electronic Industry Development Association)</strong> 在1996年制定(1.0)，1998年省级到了2.1版本，增加对了音频文件的支持。目前的最新版本是2.21 版。国际标准化组织(ISO)正在制订的相机文件设计标准（DCF -- Design role for Camera File system/相机文件系统设计规则）可能以Exif2.1为基础。</p><p>目前几乎新型的数码相机都使用Exif文件格式来存储图像.</p></blockquote><h2 id="四、exif与jpeg的关系" tabindex="-1">四、EXIF与JPEG的关系 <a class="header-anchor" href="#四、exif与jpeg的关系" aria-label="Permalink to &quot;四、EXIF与JPEG的关系&quot;">​</a></h2><blockquote><p>Basically, <strong>Exif file format is the same as JPEG file format</strong>. Exif inserts some of image/digicam information data and thumbnail image to JPEG in conformity to JPEG specification.Therefore you can view Exif format image files by JPEG compliant Internet browser/Picture viewer/Photo retouch software etc. as a usual JPEG image files.</p></blockquote><p><strong>Exif 文件实际是JPEG文件的一种，遵从JPEG标准</strong>，因此加入 EXIF 信息并不影响 JPEG 文件的查看。只是在文件头信息中增加了有关拍摄信息的内容和索引图。所以我们可以使用任何支持JPEG格式的图像工具软件观看或修改Exif文件，但打开时可能看不到Exif信息，一旦修改，Exif信息可能丢失。</p><p>简单来说，EXIF 信息就是由数码相机在拍摄过程中采集一系列的信息，然后把信息放置在我们熟知的 JPEG/TIFF 文件的头部， 也就是说 EXIF 信息是镶嵌在 JPEG/TIFF 图像文件格式内的一组拍摄参数，主要包括摄影时的光圈、快门、ISO、日期时间等各种与当时摄影条件相关的讯息，相机品牌型号，色彩编码，拍摄时录制的声音以及全球定位系统（GPS）等信息。</p><h2 id="五、jpeg两种文件结构的基本样式" tabindex="-1">五、JPEG两种文件结构的基本样式 <a class="header-anchor" href="#五、jpeg两种文件结构的基本样式" aria-label="Permalink to &quot;五、JPEG两种文件结构的基本样式&quot;">​</a></h2><p>前面我们知道JPEG文件是由各种段组成：</p><table tabindex="0"><thead><tr><th style="text-align:center;">Marker名称</th><th style="text-align:center;">Marker内容</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:center;">SOI</td><td style="text-align:center;">0xFFD8</td><td style="text-align:left;">Start Of Image</td></tr><tr><td style="text-align:center;">SOF0</td><td style="text-align:center;">0xFFC0</td><td style="text-align:left;">Start Of Frame 0</td></tr><tr><td style="text-align:center;">SOF2</td><td style="text-align:center;">0xFFC2</td><td style="text-align:left;">Start of Frame 2</td></tr><tr><td style="text-align:center;">DHT</td><td style="text-align:center;">0xFFC4</td><td style="text-align:left;">Define Huffman Table(s)</td></tr><tr><td style="text-align:center;">DQT</td><td style="text-align:center;">0xFFDB</td><td style="text-align:left;">Define Quantization Table(s)</td></tr><tr><td style="text-align:center;">DRI</td><td style="text-align:center;">0xFFDD</td><td style="text-align:left;">Define Restart Interval</td></tr><tr><td style="text-align:center;">SOS</td><td style="text-align:center;">0xFFDA</td><td style="text-align:left;">Start of Scan</td></tr><tr><td style="text-align:center;">RST0~RST7</td><td style="text-align:center;">0xFFD0 ~ 0xFFD7</td><td style="text-align:left;">Restart</td></tr><tr><td style="text-align:center;">APP0~APP15</td><td style="text-align:center;">0xFFE0 ~ 0xFFEF</td><td style="text-align:left;">Application-sepcific</td></tr><tr><td style="text-align:center;">COM</td><td style="text-align:center;">0xFFFE</td><td style="text-align:left;">Comment</td></tr><tr><td style="text-align:center;">EOI</td><td style="text-align:center;">0xFFD9</td><td style="text-align:left;">End of Image</td></tr></tbody></table><p>0xFFE0~0xFFEF之间的标记被叫做 &quot;应用标记&quot;, 它们在JPEG图像解码中不是必须存在的. 它们被使用于用户的应用程序之中。例如, 老款的olympus/canon/casio/agfa 数字相机使用 JFIF(JPEG文件交换格式/JPEG File Interchange Format)来存储图像。 JFIF 使用 APP0(0xFFE0) 标记来插入数字相机的配置信息数据和缩略图。Exif和JFIF的文件结构比较如下：</p><img src="'+r+'" alt="image-20241012070650615"><p>其实大部分字段都是一样的，主要区别就在APP0和APP1：</p><ul><li><strong>This is APP0</strong></li></ul><img src="'+n+'" alt="image-20241012192911174"><ul><li><strong>This is APP1</strong></li></ul><img src="'+d+'" alt="image-20241012200228532"><p>可以看到APP1明显多了很多的数据。</p>',28)])])}const m=e(s,[["render",o]]);export{P as __pageData,m as default};
